import os
from openai import OpenAI
from vision_client import get_vision_client
from vision_models import ImageAnalysisRequest, LabelDetectionResult

def detect_image_labels(request: ImageAnalysisRequest) -> LabelDetectionResult:
    client = get_vision_client()

    response = client.chat.completions.create(
        model="gpt-4o",  # OpenAI's multimodal model
        messages=[
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": "What are the labels or objects in this image?"},
                    {
                        "type": "image_url",
                        "image_url": {"url": request.image_url},
                    },
                ],
            }
        ],
        max_tokens=300,
    )

    labels = [choice.message.content for choice in response.choices if choice.message.content]
    return LabelDetectionResult(labels=labels)

import os
from openai import OpenAI

def get_vision_client():
    api_key = os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("OPENAI_API_KEY environment variable not set")
    return OpenAI(api_key=api_key)

from dataclasses import dataclass, field
from typing import List, Optional

@dataclass
class ImageAnalysisRequest:
    image_url: str

@dataclass
class LabelDetectionResult:
    labels: List[str] = field(default_factory=list)

@dataclass
class ImageDescriptionResult:
    description: Optional[str] = None

@dataclass
class TextDetectionResult:
    detected_text: List[str] = field(default_factory=list)

@dataclass
class SafetyScoreResult:
    score: str # e.g., "safe", "unsafe", "potentially_unsafe"
    categories: List[str] = field(default_factory=list)

@dataclass
class ImageSummaryResult:
    summary: str

@dataclass
class TranslatedTextResult:
    translated_text: str

@dataclass
class TextSafetyCheckResult:
    is_safe: bool
    unsafe_categories: List[str] = field(default_factory=list)

import os
from openai import OpenAI
from vision_client import get_vision_client
from vision_models import ImageAnalysisRequest, ImageDescriptionResult

def describe_image(request: ImageAnalysisRequest) -> ImageDescriptionResult:
    client = get_vision_client()

    response = client.chat.completions.create(
        model="gpt-4o",  # OpenAI's multimodal model
        messages=[
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": "Describe this image concisely."},
                    {
                        "type": "image_url",
                        "image_url": {"url": request.image_url},
                    },
                ],
            }
        ],
        max_tokens=100,
    )

    description = response.choices[0].message.content if response.choices else None
    return ImageDescriptionResult(description=description)

import os
from openai import OpenAI
from vision_client import get_vision_client
from vision_models import ImageSummaryResult

def summarize_visual_analysis(analysis_results: dict) -> ImageSummaryResult:
    client = get_vision_client()

    # Construct a prompt based on the analysis_results dictionary
    prompt_content = "Summarize the following visual analysis results:\n"
    for key, value in analysis_results.items():
        prompt_content += f"- {key}: {value}\n"

    response = client.chat.completions.create(
        model="gpt-4o",  # Using a text-based model for summarization
        messages=[
            {"role": "user", "content": prompt_content}
        ],
        max_tokens=500,
    )

    summary = response.choices[0].message.content if response.choices else ""
    return ImageSummaryResult(summary=summary)
